var image = String(java.getElements('#ComicPic')); 
var url= image.match(/src=\"([^"]+)\"/)[1];
var start = parseInt( url.substring(url.lastIndexOf('/') + 1).split('.')[0] );
var total = start + parseInt(String(java.getElements('#total')).match(/value=\"([^"]+)\"/)[1]);
var html = image;
for(let i=start;i<total;i++){
	var img = image.replace(new RegExp(start+'',"g"),''+i);
	html += img;
}
result = html;

source.exploreUrl:
@js:
   let result=[];
   let push=(title, id, size)=>result.push({
       "title": title,
       "url": 'https://api.momicacg.com/api/manga/comics'+','+JSON.stringify({
       "body": `{"themeId": ${id},"page": {{page}},"pagesize": 20,"OrderType": 1,"language": "zh-CN"}`,
       "method": "POST"
}),
       "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
       }
});
   bu=source.key+'/theme';
   aj=java.ajax(bu);
   let a=org.jsoup.Jsoup.parse(aj);
   let b=a.select('[truncate=""]');
   for (i in b){
        let url=b[i].attr('href'),
        id=String(url.match(/\d+$/));
        text=b[i].text();
        if (id.match(/35|31|29|25|24|23|16|14/)){
           continue
        }
        push(text, id, 0.25);
   }   
JSON.stringify(result);

