//基础替换方法
const X = (str, regPair, isLoop) => {
	if (!isLoop) {
		str = String(str).replace(regPair[0], regPair[1]);
		return str;
	}
	while (regPair[0].exec(str)) {
		str = String(str).replace(regPair[0], regPair[1]);
	}
	return str;
};
//按照数组替换，数组内容[{p:正则:r:替换值},{p:正则:r:替换值,l:是否循环替换}...]
const XArr = (str,regs) => {
	for(var i in regs){
		str = X(str,[regs[i].p,regs[i].r],regs[i].l ? regs[i].l : false);
	}
	return str;
}
