//创建密码输入（仅限登录界面）
const newPwd = (name,cols) => {
	var di = {};
	di.modual = "login";
	di.type = "password";
	di.name = name;
	di.cols= cols;
	return creatEle(di);
}
//创建下拉列表选择框（选中后执行func）
const newSelect = (name,viewName,modual,chars,func,cols) => {
	var di = {};
	di.modual = modual;
	di.type = "select";
	di.name = name;
	di.viewName= viewName;
	di.func= func;
	di.cols = cols;
	di.chars = chars;
	di.default = chars[0];
	return creatEle(di);
}
//创建切换按钮（选中后执行func）
const newToggle = (name,viewName,modual,chars,func,cols) => {
	var di = {};
	di.modual = modual;
	di.type = "toggle";
	di.name = name;
	di.viewName= viewName;
	di.func= func;
	di.cols = cols;
	di.chars = chars;
	di.default = chars[0];
	return creatEle(di);
}

