        .chat-section { border: none !important; box-shadow: 0 4px 16px rgba(0,0,0,0.06) !important; background: var(--card) !important; border-radius: 14px !important; padding: 10px 10px 6px !important; }
        .chat-messages { padding: 2px 0 6px !important; }
        .chat-messages::-webkit-scrollbar { width: 4px; }
        .chat-messages::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.18); border-radius: 4px; }
        .chat-messages:empty::after { content: '暂无弹幕，来说点什么吧~'; display: block; text-align: center; color: var(--muted); font-size: 13px; padding: 40px 0; }
        .message-wrapper { margin-bottom: 7px !important; }
        .message-item { padding: 8px 12px !important; border-radius: 14px !important; border: none !important; background: #f6f7f9 !important; font-size: 14px !important; line-height: 1.45 !important; color: var(--text); box-shadow: 0 1px 2px rgba(0,0,0,0.03); }
        .message-item .user-name { color: var(--accent); font-weight: 700; margin-right: 4px; }
        .level-tag { display: inline-block; padding: 1px 6px; margin-right: 5px; border-radius: 8px; font-size: 11px; font-weight: 700; color: #7a4b00; background: linear-gradient(135deg, #ffe08a, #ffc44d); }
        .tip-item { background: linear-gradient(135deg, #fff4e5, #ffe6c7) !important; border: 1px solid #ffd8a8 !important; }
        .tip-item .tip-amount { color: var(--accent2); font-weight: 800; }
        .system-message { background: transparent !important; text-align: center; color: var(--muted) !important; font-size: 12px !important; box-shadow: none !important; padding: 4px 0 !important; }
        .floating-panel { border-radius: 18px !important; border: none !important; box-shadow: 0 16px 48px rgba(0,0,0,0.22) !important; padding: 18px !important; }
        .floating-panel-title { font-size: 17px; font-weight: 800; color: var(--text); margin-bottom: 12px; }
        .floating-info-section-title { color: var(--accent) !important; font-weight: 700; }
        #bottomBar .floating-button { background: linear-gradient(135deg, var(--accent), var(--accent2)) !important; box-shadow: 0 4px 14px rgba(255,59,92,0.35); font-size: 18px; }
        #cs { background: linear-gradient(135deg, var(--accent), var(--accent2)) !important; box-shadow: 0 3px 10px rgba(255,59,92,0.28); }
        #ci { background: #f2f3f7 !important; border-color: transparent !important; }
        #ci:focus { background: #fff !important; border-color: var(--accent) !important; }
        .loading-indicator { border-radius: 20px !important; background: rgba(0,0,0,0.65) !important; color: #fff !important; padding: 8px 18px !important; font-size: 13px; }
        /* 点击画面只显示控制条（中央按钮负责播放/暂停） */
        /* ===== 控制栏移动端压缩间距（单行不重叠） ===== */
        @media (max-width: 520px) {
            .custom-controls { padding: 16px 8px 6px; gap: 4px; }
            .left-controls, .right-controls { gap: 4px; }
            .control-btn { width: 32px; height: 32px; font-size: 14px; }
            .rotate-btn { padding: 5px 7px; font-size: 11px; }
            .selector-btn { padding: 4px 6px; font-size: 11px; min-width: 44px; gap: 3px; }
            .selector-menu { bottom: 36px; }
        }
    </style>
<body>
    <div id="config" style="display:none;">
        <div id="liveData" style="display:none;">__LIVE_DATA__</div>
    </div>

    <div class="app-container">
        <div class="live-section">


